using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
namespace Underwater.Editor {
public static class CompactDolphinPatrol {
 const string Scene="Assets/Scenes/Underwater_Realistic.unity",Output="Renders/CompactDolphins/";
 public static void Run(){
 var scene=EditorSceneManager.OpenScene(Scene);var actors=UnityEngine.Object.FindObjectsByType<DolphinSwimController>(FindObjectsSortMode.None).OrderBy(d=>d.podIndex).ToArray();if(actors.Length!=3)throw new Exception("Expected three dolphins");var anchor=actors[0].GetComponent<WreckCreature>().habitatCenter;var radii=new Vector2(4.5f,4);Vector3 selected=default;bool found=false;
 var offsets=new[]{Vector3.zero,new Vector3(2,0,0),new Vector3(-2,0,0),new Vector3(0,0,2),new Vector3(0,0,-2),new Vector3(2,0,2),new Vector3(-2,0,-2)};
 for(int h=0;h<=32&&!found;h++)foreach(var offset in offsets){var center=anchor+offset+Vector3.up*(h*.25f);if(ClearCourse(actors[0],center,radii)){selected=center;found=true;break;}}
 if(!found)throw new Exception("No compact route clears the wreck");
 foreach(var d in actors){d.compactPatrol=true;d.compactCenter=selected;d.compactRadii=radii;d.compactSpeed=.58f;d.compactStartAngle=d.podIndex*Mathf.PI*2/3;float a=d.compactStartAngle;d.transform.SetPositionAndRotation(selected+new Vector3(radii.x*Mathf.Sin(a),Mathf.Sin(a+d.podIndex)*.08f,radii.y*Mathf.Cos(a)),Quaternion.LookRotation(new Vector3(radii.x*Mathf.Cos(a),Mathf.Cos(a+d.podIndex)*.08f,-radii.y*Mathf.Sin(a)),Vector3.up));EditorUtility.SetDirty(d);}Physics.SyncTransforms();EditorSceneManager.SaveScene(scene);Directory.CreateDirectory(Output);File.WriteAllText(Output+"Placement.txt","Compact centre="+selected+"; radii="+radii+"; cruise speed=0.58 m/s. Entire route swept at body radius + 0.35 m.\n");Validate();Debug.Log("COMPACT_DOLPHINS_CONFIGURED");
 }
 static bool ClearCourse(DolphinSwimController d,Vector3 center,Vector2 r){var body=d.GetComponent<ReefSphereBody>();var ground=d.GetComponent<ReefAnimalClearance>();float radius=body.radius+.35f;var previous=center+new Vector3(0,0,r.y);for(int i=0;i<=120;i++){float a=i*Mathf.PI*2/120;var p=center+new Vector3(r.x*Mathf.Sin(a),0,r.y*Mathf.Cos(a));var rotation=Quaternion.LookRotation(new Vector3(r.x*Mathf.Cos(a),0,-r.y*Mathf.Sin(a)),Vector3.up);if(!ground.RequiredHeight(p,rotation,out var floor)||p.y<floor+.15f)return false;if(Physics.CheckSphere(p,radius,1<<8,QueryTriggerInteraction.Ignore))return false;var v=p-previous;if(v.sqrMagnitude>.000001f&&Physics.SphereCast(previous,radius,v.normalized,out _,v.magnitude,1<<8,QueryTriggerInteraction.Ignore))return false;previous=p;}return true;}
 public static void Validate(){EditorSceneManager.OpenScene(Scene);var actors=UnityEngine.Object.FindObjectsByType<DolphinSwimController>(FindObjectsSortMode.None).OrderBy(d=>d.podIndex).ToArray();float[] travel=new float[3],stop=new float[3];float maxStop=0,maxRange=0,minGap=float.MaxValue;for(int f=0;f<12000;f++){for(int i=0;i<3;i++){var d=actors[i];var body=d.GetComponent<ReefSphereBody>();var before=body.WorldCenter;d.GetComponent<WreckCreature>().Step(.05f);d.GetComponent<ReefAnimalClearance>().Enforce();Physics.SyncTransforms();float moved=(body.WorldCenter-before).magnitude;travel[i]+=moved;stop[i]=moved<.005f*.05f?stop[i]+.05f:0;maxStop=Mathf.Max(maxStop,stop[i]);maxRange=Mathf.Max(maxRange,Vector3.ProjectOnPlane(d.transform.position-d.compactCenter,Vector3.up).magnitude);if(!body.Clear(d.transform.position))throw new Exception("Compact patrol overlaps reef");}for(int i=0;i<3;i++)for(int j=i+1;j<3;j++)minGap=Mathf.Min(minGap,Vector3.Distance(actors[i].transform.position,actors[j].transform.position));}
 Directory.CreateDirectory(Output);File.WriteAllText(Output+"Validation.txt","10-minute compact patrol: travel="+string.Join(",",travel)+" m; max distance from centre="+maxRange+" m; longest stop="+maxStop+" s; closest spacing="+minGap+" m.\n");if(maxStop>1||maxRange>4.7f||minGap<3.5f||travel.Any(d=>d<100))throw new Exception("Compact patrol limits failed");EditorSceneManager.OpenScene(Scene);}
}
}
